import {rememberOwnedMoves} from './learning-access.js?v=0.90.48';
export const SALVATION_ID=470;
export const SALVATION_MOVE={id:SALVATION_ID,name:'Mercy Edge',type_id:'FAIRY',category:'PHYSICAL',power:60,accuracy:100,pp:20,priority:0,target:'SINGLE_FOE',effects:[],adaptiveCategory:false,nonlethal:true,contact:false,salvation:true,tutor:'Walter',effect_text:'Uses Attack or Special Attack, whichever is higher. Direct damage cannot reduce a living target below 1 HP. Critical hits and damage boosts retain that limit. Poison, burn and other turn-end effects still apply.',authored_visual_action:'An ivory-gold blade or pulse halts at the foe; broken rays fold into a protective First Light seal and a single ember remains.',provenance:{authoring:'Universal Walter restraint tutor, user request 2026-10-14'}};
export function resolveSalvationMove(unit,move){return move?.adaptiveCategory?{...move,category:(unit.stats.sp_attack>unit.stats.attack?'SPECIAL':'PHYSICAL')}:move;}
export function installSalvation(data){if(!data.moves.some(m=>m.id===SALVATION_ID))data.moves.push(SALVATION_MOVE);}
export function teachSalvation(unit,slot){if(!unit||unit.hp<=0||unit.dead)return false;const existing=unit.moves.find(m=>m.id===SALVATION_ID);if(existing)return false;const special=unit.stats.sp_attack>unit.stats.attack,move={...SALVATION_MOVE,id:special?710:470,name:special?'Mercy Ray':'Mercy Edge',category:special?'SPECIAL':'PHYSICAL',left:SALVATION_MOVE.pp};if(slot===-1){if(unit.moves.length>=4)return false;rememberOwnedMoves(unit);unit.moves.push(move);rememberOwnedMoves(unit);return true;}if(!Number.isInteger(slot)||slot<0||slot>=unit.moves.length)return false;rememberOwnedMoves(unit);unit.moves[slot]=move;rememberOwnedMoves(unit);return true;}
export function salvationHTML(move,result){if(result.missed||result.immune||result.skipped)return `<div class="fx-message">${result.missed?'MISS':result.immune?'IMMUNE':'ACTION STOPPED'}</div>`;return `<div class="salvation-fx ${move.category==='SPECIAL'?'salvation-pulse':'salvation-blade'} ${result.missed||result.immune||result.skipped?'salvation-miss':''}" data-fx-move="470"><i class="salvation-halo"></i><svg class="salvation-emblem" viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="37"/><path d="M50 13V87M21 40H79M32 70L50 82 68 70M36 18L50 6 64 18"/></svg><i class="salvation-stroke" style="--salvation-source-x:var(--source-x,0px);--salvation-source-y:var(--source-y,0px)"></i>${Array.from({length:8},(_,i)=>`<i class="salvation-ray" style="--i:${i}"></i>`).join('')}${result.damage?`<div class="impact-number ${result.critical?'critical-number':''}" style="animation-delay:960ms">−${result.damage}</div>`:''}<b class="salvation-ember">${result.remainingHp===1?'1 HP · MERCY':'SALVATION'}</b></div>`;}

